package com.movieticket.show; import jakarta.persistence.*;
@Entity @Table(name="seats",uniqueConstraints=@UniqueConstraint(name="uk_show_seat",columnNames={"show_id","seat_number"})) public class Seat {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="show_id",nullable=false) private Long showId; @Column(name="seat_number",nullable=false) private String seatNumber; @Column(nullable=false) private boolean reserved=false; public Seat(){} public Seat(Long s,String n){showId=s;seatNumber=n;} public Long getId(){return id;} public Long getShowId(){return showId;} public String getSeatNumber(){return seatNumber;} public boolean isReserved(){return reserved;} public void setReserved(boolean v){reserved=v;} }
